mapper.select:
SELECT c.*, u.nickname AS sender_name, u.avatar AS sender_avatar, p.title AS post_title, p.user_id AS post_user_id FROM post_comments AS c LEFT JOIN users AS u ON c.user_id = u.id INNER JOIN posts AS p ON p.id = c.post_id WHERE c.deleted_at IS NULL AND p.deleted_at IS NULL
AND c.status = #{status}
ORDER BY c.created_at DESC LIMIT #{offset}, #{limit}

mapper.insert:
INSERT INTO post_comments (
    post_id, user_id, parent_id, root_id, content, status
) VALUES (
    #{postId}, #{senderId}, #{parentId}, #{rootId}, #{content}, #{status}
)

mapper.update:
UPDATE post_comments
SET status = #{status}
WHERE id = #{id} AND status = 'pending' AND deleted_at IS NULL

UPDATE post_comments
SET status = #{status}
WHERE id = #{id}
  AND status = #{currentStatus}
  AND deleted_at IS NULL

UPDATE post_comments
SET status = #{status}
WHERE id = #{id}
  AND status != #{status}
  AND deleted_at IS NULL
